-- Allow cancellation/rescheduling queue messages generated by controlled tenant trigger.
-- Do not backfill old appointments. Other tenants unaffected because trigger is Julli-only.
alter table public.agenda_whatsapp_queue
  drop constraint if exists agenda_whatsapp_queue_message_type_check;
alter table public.agenda_whatsapp_queue
  add constraint agenda_whatsapp_queue_message_type_check
  check (message_type in ('confirmation','reminder','followup','cancellation','rescheduled'));

create or replace function agenda_private.queue_julli_appointment_changes()
returns trigger
language plpgsql
security definer
set search_path = public, agenda_private, pg_temp
as $fn$
declare
  v_kind text;
  v_customer_name text;
  v_phone text;
  v_service text;
  v_business text;
  v_content text;
begin
  if tg_op <> 'UPDATE' or new.business_id <> '7f00c45b-b228-4ee8-b795-aadbdcfb9d45'::uuid then
    return new;
  end if;
  -- The Julli-only pilot must remain explicitly enabled.
  if not exists (
    select 1 from agenda_private.whatsapp_dispatch_pilot p
    where p.business_id=new.business_id and p.enabled and p.activated_at is not null
  ) then return new; end if;

  if new.status='cancelled' and old.status is distinct from 'cancelled' then
    v_kind:='cancellation';
  elsif old.starts_at is distinct from new.starts_at
        and new.status not in ('cancelled','completed','no_show')
        and old.status is distinct from 'cancelled' then
    v_kind:='rescheduled';
  else
    return new;
  end if;

  -- Do not alert about old, already elapsed appointments.
  if new.starts_at<=now() then return new; end if;

  select c.name,c.phone into v_customer_name,v_phone
  from public.agenda_customers c
  where c.id=new.customer_id and c.business_id=new.business_id;
  if nullif(btrim(coalesce(v_phone,'')),'') is null then return new; end if;

  select s.name into v_service from public.agenda_services s
  where s.id=new.service_id and s.business_id=new.business_id;
  select regexp_replace(b.name,'^by[[:space:]]+','','i')
  into v_business from public.agenda_businesses b where b.id=new.business_id;

  if v_kind='cancellation' then
    v_content:=format(
      'Olá, %s! Seu horário na *%s* para *%s* foi cancelado. Se precisar reagendar, entre em contato conosco.',
      split_part(btrim(coalesce(v_customer_name,'Cliente')),' ',1),
      coalesce(v_business,'Agenda Pro'),
      to_char(new.starts_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI')
    );
  else
    v_content:=format(
      'Olá, %s! Seu horário na *%s* foi reagendado.%s%sHorário anterior: *%s*%sNovo horário: *%s*%sServiço: *%s*.%s%sTe esperamos!',
      split_part(btrim(coalesce(v_customer_name,'Cliente')),' ',1),
      coalesce(v_business,'Agenda Pro'),
      chr(10),chr(10),
      to_char(old.starts_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),chr(10),
      to_char(new.starts_at at time zone 'America/Sao_Paulo','DD/MM/YYYY HH24:MI'),chr(10),
      coalesce(v_service,'Atendimento'),chr(10),chr(10)
    );
  end if;

  insert into public.agenda_whatsapp_queue (
    business_id,appointment_id,customer_id,message_type,scheduled_for,status,
    customer_name,customer_phone,service_name,professional_name,starts_at,
    notification_text,delivery_semantics,updated_at
  ) values (
    new.business_id,new.id,new.customer_id,v_kind,now(),'pending',
    v_customer_name,v_phone,v_service,new.professional_name,new.starts_at,
    v_content,'AT_MOST_ONCE',now()
  )
  on conflict(appointment_id,message_type) do update set
    scheduled_for=excluded.scheduled_for,
    customer_name=excluded.customer_name,
    customer_phone=excluded.customer_phone,
    professional_name=excluded.professional_name,
    starts_at=excluded.starts_at,
    notification_text=excluded.notification_text,
    updated_at=now()
  where public.agenda_whatsapp_queue.status='pending'
    and public.agenda_whatsapp_queue.attempts=0
    and public.agenda_whatsapp_queue.dispatch_started_at is null;

  return new;
end;
$fn$;

revoke all on function agenda_private.queue_julli_appointment_changes() from public,anon,authenticated;

drop trigger if exists zz_agenda_julli_change_notifications on public.agenda_appointments;
create trigger zz_agenda_julli_change_notifications
after update of starts_at,status on public.agenda_appointments
for each row execute function agenda_private.queue_julli_appointment_changes();

-- Keep legacy trigger DISABLED. It can reset statuses and retry already sent messages.
alter table public.agenda_appointments disable trigger zz_agenda_appointment_changes;
